1	import { readFile } from 'node:fs/promises';
2	import { charIn, createRegExp } from 'magic-regexp';
3	import { join, resolve } from 'pathe';
4	import { canonicalize, sha256 } from './canonicalize.ts';
5	
6	/**
7	 * The pigallery2 1.7.0 Angular holdout falsification receipt.
8	 *
9	 * This is the Angular counterpart of the cypress-realworld-app record, and it
10	 * is published for the same reason: an adapter that only publishes the
11	 * applications it carried is not evidence. pigallery2 was ingested after the
12	 * adapters were frozen, was never fixtured or adapted before it, and its
13	 * migrated build has never produced an artifact. T018 measured it against the
14	 * frozen 4df7bc96 composition and it stopped at the resolver with seven itemised
15	 * gaps. T021 then reopened the Angular subtree under board authorization and
16	 * chased it through four units and twelve generic capabilities; the migrated
17	 * closure now installs and the compiler now reads the application, and the
18	 * build still refuses.
19	 *
20	 * What is left is not a gap in the engine. It is three libraries that stop at
21	 * pre-Ivy bytes and have no published Ivy successor, used by this application
22	 * at six import sites it authored. Angular 16 removed ngcc, so those bytes are
23	 * unconsumable at the 16 cell by any transform that does not edit the
24	 * application. That is a support boundary, and it is declared as one here
25	 * rather than being worked around: the RED stands, the boundary is published,
26	 * and neither is softened by the other.
27	 *
28	 * Every field below is derived from the committed run evidence — the sealed
29	 * `attempt.json` and the two u4 lane logs — rather than authored here, so the
30	 * receipt cannot drift away from what the run measured.
31	 */
32	export const HOLDOUT_ANGULAR_PIGALLERY2_SCHEMA =
33		'versionless.holdout-angular-pigallery2.v1' as const;
34	export const HOLDOUT_ANGULAR_PIGALLERY2_RECEIPT_PATH =
35		'evidence/runs/holdout-angular-pigallery2/receipt.json' as const;
36	export const HOLDOUT_ANGULAR_PIGALLERY2_MARKDOWN_PATH =
37		'evidence/runs/holdout-angular-pigallery2/receipt.md' as const;
38	export const HOLDOUT_ANGULAR_PIGALLERY2_ATTEMPT_PATH =
39		'evidence/ingests/angular-pigallery2-v1-7-0/attempt.json' as const;
40	export const HOLDOUT_ANGULAR_PIGALLERY2_FIXTURE = 'angular-pigallery2-v1-7-0' as const;
41	export const HOLDOUT_ANGULAR_PIGALLERY2_APPLICATION = 'pigallery2' as const;
42	export const HOLDOUT_ANGULAR_PIGALLERY2_INGEST_UNIT =
43		'lrapr-t018/u1-license-prescreen-ingest' as const;
44	export const HOLDOUT_ANGULAR_PIGALLERY2_PUBLISHING_UNIT =
45		'lrapr-t023/u1-boundary-publish-refreeze' as const;
46	
47	/**
48	 * The committed run evidence this receipt is derived from, bound by exact
49	 * bytes. Re-deriving the receipt against edited run evidence fails here rather
50	 * than silently republishing a different measurement under the same name.
51	 */
52	export const HOLDOUT_ANGULAR_PIGALLERY2_RUN_EVIDENCE = Object.freeze([
53		Object.freeze({
54			path: HOLDOUT_ANGULAR_PIGALLERY2_ATTEMPT_PATH,
55			sha256: '222fd0ab7e4fa2c6b462d306534eeb82c88b47c37bd102093ecbce12d4e25fbb',
56		}),
57		Object.freeze({
58			path: 'evidence/ingests/angular-pigallery2-v1-7-0/migration/t021-u4-lane-install.log',
59			sha256: 'af3cac2a3c9803958f2927e83832c5f741aa08c44b7e787e1224bb5ca7fb467b',
60		}),
61		Object.freeze({
62			path: 'evidence/ingests/angular-pigallery2-v1-7-0/migration/t021-u4-lane-build-run1.log',
63			sha256: '47231a5f3b39ae05f9d36a9c9a0baf579633478383b207bd1d4b6ea48370226e',
64		}),
