67	/**
68	 * The freeze the falsification was taken under, and the freeze the final
69	 * measurement's adapter bytes are now published as.
70	 *
71	 * Both are recorded because both are true of different runs and neither is a
72	 * substitute for the other: T018 ran against the frozen 4df7bc96 composition
73	 * with zero adapter bytes changed, and the last T021 build ran against the
74	 * Angular subtree oid `1f63f32c`, which is exactly the tree the f1a63359
75	 * re-freeze publishes. The reopen between them was authorized and is named, so
76	 * a reader is never asked to assume the adapter stood still when it did not.
77	 */
78	export const HOLDOUT_ANGULAR_PIGALLERY2_FROZEN_FINGERPRINT =
79		'4df7bc961033fc5856b4d58e0bca9f11ad2aa9d43aaaee726956f34d209b37e7' as const;
80	export const HOLDOUT_ANGULAR_PIGALLERY2_ANGULAR_SUBTREE_AT_WALL =
81		'1f63f32c9f4eb327e2c85f63e69544f1eeb99428' as const;
