83	/** The missing capability the run measured, named exactly once. */
84	export const HOLDOUT_ANGULAR_PIGALLERY2_MISSING_CAPABILITY =
85		'consumption of pre-Ivy-only dependencies with no published Ivy successor at the Angular 16 target cell' as const;
