87	/**
88	 * The declared support boundary this holdout established.
89	 *
90	 * It is a limitation, published as data so the matrix and the enterprise
91	 * reports carry it rather than a prose footnote somebody has to remember to
92	 * repeat. A declared boundary is not a weakened gate: nothing in the corpus is
93	 * reclassified by it, no numerator moves, and the application that proved it
94	 * stays RED.
95	 */
96	export const ANGULAR_PRE_IVY_SUPPORT_BOUNDARY = Object.freeze({
97		id: 'angular-16-pre-ivy-only-dependency',
98		lineage: 'angular',
99		cell: 'angular-16-browser-builder',
100		state: 'unsupported',
101		declaredBy: 'lrapr-t022 boundary ruling (Judge, 2026-08-14)',
102		publishedBy: HOLDOUT_ANGULAR_PIGALLERY2_PUBLISHING_UNIT,
103		condition:
104			'pre-Ivy-only dependencies (no published Ivy successor) in active application use => unsupported at the Angular 16 target cell',
105		mechanism:
106			'Angular 16 removed ngcc, so ViewEngine bytes cannot be consumed at this cell, and a library whose last published version is pre-Ivy has no successor to align to. Carrying such an application would require editing its source at the import sites, which is an application change rather than a migration the engine can perform.',
107		certification: 'not-certified: this cell is declared unsupported, not tested-and-failed-once',
108		instanceEvidence: {
109			application: HOLDOUT_ANGULAR_PIGALLERY2_APPLICATION,
110			receipt: HOLDOUT_ANGULAR_PIGALLERY2_RECEIPT_PATH,
111			libraries: 3,
112			importSites: 6,
113		},
114		nonclaims: [
115			'No claim that every application carrying a pre-Ivy-only dependency is unmigratable in general: the boundary is declared at the Angular 16 target cell, which is the only Angular cell this engine has.',
116			'No claim that this boundary is unreachable: an ngcc-bearing multi-hop cell (Angular 12 or 13) would consume those bytes. It is a declared tranche-two commitment, not a silent deferral, and it invalidates every Angular 16 cell reading in this record, so it is not taken here.',
117			'No claim that the boundary excuses the pigallery2 RED. The RED is permanent falsification evidence and is published unchanged alongside this declaration.',
118		],
119	});
