121	/**
122	 * The three libraries the wall is made of, and every application site that
123	 * needs them.
124	 *
125	 * These are authored here as structured data and then checked against the
126	 * sealed run record: each library name, each version the registry stops at, and
127	 * each `path:line` below must appear verbatim in the run's own wall text, or
128	 * derivation fails. Structure that cannot be checked against the measurement is
129	 * decoration, so this one is checked.
130	 */
131	export const HOLDOUT_ANGULAR_PIGALLERY2_WALL = Object.freeze([
132		Object.freeze({
133			library: '@yaga/leaflet-ng2',
134			lastPublishedVersion: '1.1.0',
135			verdict:
136				'stops at 1.1.0, built against Angular 12 in full compilation mode with no partial declarations for a linker to read',
137			importSites: Object.freeze([
138				'frontend/app/app.module.ts:14',
139				'frontend/app/ui/gallery/map/map.gallery.component.ts:7',
140				'frontend/app/ui/gallery/map/lightbox/lightbox.map.gallery.component.ts:16',
141			]),
142		}),
143		Object.freeze({
144			library: 'ng2-slim-loading-bar',
145			lastPublishedVersion: '4.0.0',
146			verdict: 'stops at 4.0.0, whose declared peer is @angular/core "^2.4.7 || ^4.0.0"',
147			importSites: Object.freeze([
148				'frontend/app/app.module.ts:31',
149				'frontend/app/model/network/network.service.ts:4',
150			]),
151		}),
152		Object.freeze({
153			library: 'jw-bootstrap-switch-ng2',
154			lastPublishedVersion: '2.0.5',
155			verdict: 'stops at 2.0.5, a pre-Ivy ViewEngine package, on a cell whose ngcc is a stub',
156			importSites: Object.freeze(['frontend/app/app.module.ts:41']),
157		}),
