160	/**
161	 * What this receipt does not claim, over and above the run's own non-claims.
162	 */
163	export const HOLDOUT_ANGULAR_PIGALLERY2_ADDED_NONCLAIMS = Object.freeze([
164		'No browser evidence exists for either lane. No journey ran, no page was loaded, and nothing is claimed about behavior.',
165		'No claim that the twelve capabilities the chase extracted are proven: every one of them was written against this single application, whose migrated build is RED, and all twelve stay experimental and out of the supported matrix.',
166		'No claim that a green holdout would have proven generic Angular support. The caveat is carried here in the failing direction too.',
