176	export interface HoldoutAngularPigallery2Receipt {
177		schemaVersion: typeof HOLDOUT_ANGULAR_PIGALLERY2_SCHEMA;
178		role: 'holdout';
179		holdoutOutcome: 'failed';
180		reason: typeof HOLDOUT_ANGULAR_PIGALLERY2_MISSING_CAPABILITY;
181		ingestUnit: typeof HOLDOUT_ANGULAR_PIGALLERY2_INGEST_UNIT;
182		measuringUnit: string;
183		publishedBy: typeof HOLDOUT_ANGULAR_PIGALLERY2_PUBLISHING_UNIT;
184		fixture: typeof HOLDOUT_ANGULAR_PIGALLERY2_FIXTURE;
185		application: typeof HOLDOUT_ANGULAR_PIGALLERY2_APPLICATION;
186		framework: 'angular';
187		source: {
188			repository: string;
189			release: string;
190			revision: string;
191			archiveSha256: string;
192			license: string;
193			licenseSha256: string;
194			angular: string;
195			angularCli: string;
196			typescript: string;
