207				statement: string;
208			};
209			holdoutSpecificConfiguration: 'none';
210			applicationFilesHandEdited: 0;
211		};
212		cell: { id: string; angularLine: string; builder: string; node: string };
213		lanes: {
214			baseline: { outcome: 'green'; toolchain: string; statement: string };
215			migrated: {
216				outcome: 'red';
217				installs: true;
218				buildsAttempted: number;
219				diagnosticsAtWall: number;
220				diagnosticsBeforeWall: number;
221				artifactProduced: false;
222				statement: string;
223			};
224		};
