240	const sha256Hex = createRegExp(
241		charIn('0123456789').from('a', 'f').times(64).at.lineStart().at.lineEnd(),
242	);
243	
244	function record(value: unknown, label: string): Record<string, unknown> {
245		if (typeof value !== 'object' || value === null || Array.isArray(value))
246			throw new Error(`${label} is not an object`);
247		return value as Record<string, unknown>;
248	}
249	
250	function text(value: unknown, label: string): string {
251		if (typeof value !== 'string' || value.length === 0) throw new Error(`${label} is not a string`);
252		return value;
253	}
254	
255	function count(value: unknown, label: string): number {
256		if (typeof value !== 'number' || !Number.isInteger(value)) throw new Error(`${label} is not an integer`);
257		return value;
258	}
