260	/** The canonical digest of a receipt, taken with the digest field emptied. */
261	export function holdoutAngularPigallery2Digest(receipt: HoldoutAngularPigallery2Receipt): string {
262		const copy = structuredClone(receipt);
263		copy.integrity.canonicalDigest = '';
264		return sha256(canonicalize(copy));
265	}
