267	/**
268	 * Reads the sealed attempt record and rebuilds the receipt from it.
269	 *
270	 * The wall structure above is checked against this record rather than trusted:
271	 * every library, every version the readings stop at and every import site must
272	 * appear in the run's own wall text.
273	 */
274	export async function deriveHoldoutAngularPigallery2Receipt(
275		rootDir = '.',
276	): Promise<HoldoutAngularPigallery2Receipt> {
277		const root = resolve(rootDir);
278		for (const evidence of HOLDOUT_ANGULAR_PIGALLERY2_RUN_EVIDENCE) {
279			const bytes = await readFile(join(root, evidence.path));
280			if (sha256(bytes.toString('utf8')) !== evidence.sha256)
281				throw new Error(`pigallery2 holdout run evidence changed: ${evidence.path}`);
282		}
283		const attempt = record(
284			JSON.parse(await readFile(join(root, HOLDOUT_ANGULAR_PIGALLERY2_ATTEMPT_PATH), 'utf8')),
285			'pigallery2 attempt record',
286		);
287		const candidate = record(attempt.candidate, 'pigallery2 candidate');
288		const gateZero = record(attempt.gateZero, 'pigallery2 gate zero');
289		const licenseAtPin = record(gateZero.licenseAtPin, 'pigallery2 license at pin');
290		const detect = record(attempt.detect, 'pigallery2 detection');
291		const angular = record(detect.angular, 'pigallery2 Angular detection');
292		const cliGeneration = record(detect.angularCliGeneration, 'pigallery2 CLI generation');
293		const baseline = record(attempt.baseline, 'pigallery2 baseline');
294		const identityCheck = record(baseline.identityCheck, 'pigallery2 archive identity');
295		const migration = record(attempt.migration, 'pigallery2 migration');
296		const freeze = record(migration.freeze, 'pigallery2 migration freeze');
297		const cell = record(migration.cell, 'pigallery2 target cell');
298		const targetBuild = record(migration.targetBuild, 'pigallery2 target build');
299		const wall = record(migration.u4Wall, 'pigallery2 u4 wall');
300		const wallText = JSON.stringify(wall);
301	
302		if (freeze.compositeFingerprint !== HOLDOUT_ANGULAR_PIGALLERY2_FROZEN_FINGERPRINT)
303			throw new Error('pigallery2 holdout was not measured under the recorded frozen composite');
304		if (migration.outcome !== 'red-migration-gaps-itemised' || targetBuild.produced !== false)
305			throw new Error('pigallery2 holdout attempt record no longer states a RED with no artifact');
306		for (const entry of HOLDOUT_ANGULAR_PIGALLERY2_WALL) {
307			if (!wallText.includes(entry.library) || !wallText.includes(entry.lastPublishedVersion))
308				throw new Error(`pigallery2 wall record omits ${entry.library}`);
309			for (const site of entry.importSites)
310				if (!wallText.includes(site))
311					throw new Error(`pigallery2 wall record omits import site ${site}`);
312		}
313		const importSites = HOLDOUT_ANGULAR_PIGALLERY2_WALL.reduce(
314			(total, entry) => total + entry.importSites.length,
315			0,
316		);
317		if (HOLDOUT_ANGULAR_PIGALLERY2_WALL.length !== 3 || importSites !== 6)
318			throw new Error('pigallery2 wall is not the declared three libraries at six sites');
319	
320		const receipt: HoldoutAngularPigallery2Receipt = {
321			schemaVersion: HOLDOUT_ANGULAR_PIGALLERY2_SCHEMA,
322			role: 'holdout',
323			holdoutOutcome: 'failed',
324			reason: HOLDOUT_ANGULAR_PIGALLERY2_MISSING_CAPABILITY,
325			ingestUnit: HOLDOUT_ANGULAR_PIGALLERY2_INGEST_UNIT,
326			measuringUnit: text(wall.unit, 'pigallery2 wall unit'),
327			publishedBy: HOLDOUT_ANGULAR_PIGALLERY2_PUBLISHING_UNIT,
328			fixture: HOLDOUT_ANGULAR_PIGALLERY2_FIXTURE,
329			application: HOLDOUT_ANGULAR_PIGALLERY2_APPLICATION,
330			framework: 'angular',
331			source: {
332				repository: text(candidate.repository, 'pigallery2 repository'),
333				release: text(candidate.requestedRelease, 'pigallery2 release'),
334				revision: text(migration.commit, 'pigallery2 revision'),
335				archiveSha256: text(identityCheck.measuredSha256, 'pigallery2 archive digest'),
336				license: text(licenseAtPin.spdx, 'pigallery2 license'),
337				licenseSha256: text(licenseAtPin.sha256, 'pigallery2 license digest'),
338				angular: text(angular.framework, 'pigallery2 Angular version'),
339				angularCli: text(cliGeneration.cli, 'pigallery2 Angular CLI'),
340				typescript: text(angular.typescript, 'pigallery2 TypeScript version'),
341			},
342			runEvidence: HOLDOUT_ANGULAR_PIGALLERY2_RUN_EVIDENCE.map((entry) => ({ ...entry })),
343			frozenAdapter: {
344				compositeFingerprintAtIngestion: HOLDOUT_ANGULAR_PIGALLERY2_FROZEN_FINGERPRINT,
345				bytesChangedAtIngestion: 0,
346				authorizedReopen: {
347					task: 'T021',
348					subtree: 'packages/frameworks/angular',
349					capabilitiesExtracted: 12,
350					angularSubtreeOidAtWall: HOLDOUT_ANGULAR_PIGALLERY2_ANGULAR_SUBTREE_AT_WALL,
351					statement:
352						'T018 ran this application against the frozen 4df7bc96 composition with zero adapter bytes changed. T021 then reopened the Angular subtree under board authorization and extracted twelve generic capabilities from the falsification; the final build below ran against Angular subtree oid 1f63f32c, which is the tree the f1a63359 re-freeze publishes. No capability branches on this application, and no application source file was hand-edited in any unit.',
353				},
354				holdoutSpecificConfiguration: 'none',
355				applicationFilesHandEdited: 0,
356			},
357			cell: {
358				id: text(cell.id, 'pigallery2 cell id'),
359				angularLine: text(cell.angularLine, 'pigallery2 Angular line'),
360				builder: text(cell.builder, 'pigallery2 builder'),
361				node: text(cell.node, 'pigallery2 cell node'),
362			},
363			lanes: {
364				baseline: {
365					outcome: 'green',
366					toolchain: "the application's own era toolchain (Node 10.24.1, npm 6.14.12)",
367					statement: text(baseline.result, 'pigallery2 baseline result'),
368				},
369				migrated: {
370					outcome: 'red',
371					installs: true,
372					buildsAttempted: 3,
373					diagnosticsAtWall: count(wall.diagnostics, 'pigallery2 wall diagnostics'),
374					diagnosticsBeforeWall: count(wall.before, 'pigallery2 pre-wall diagnostics'),
375					artifactProduced: false,
376					statement:
377						'The migrated closure installs from the manifest as authored and the compiler reads the application. Three successive migrated builds refused at the compiler and emitted nothing; the movement across them is itemised in the sealed attempt record.',
378				},
379			},
380			finding: {
381				missingCapability: HOLDOUT_ANGULAR_PIGALLERY2_MISSING_CAPABILITY,
382				verdict:
383					'the frozen Angular adapter does not carry this application, and the reason is a declared support boundary rather than a missing transform',
384				statement:
385					'Three libraries this application imports stop at pre-Ivy bytes and have no published Ivy successor. Angular 16 removed ngcc, so those bytes cannot be consumed at the target cell, and there is no version to align to. Every transform that would clear them edits the application at its six import sites, which is an application change and not a migration. The engine has no capability positioned there, and adding one would be adding an application edit.',
386				wall: HOLDOUT_ANGULAR_PIGALLERY2_WALL.map((entry) => ({
387					...entry,
388					importSites: [...entry.importSites],
389				})),
390				libraries: 3,
391				importSites: 6,
392				downstreamReading: text(migration.downstreamReading, 'pigallery2 downstream reading'),
393				actionTaken:
394					'none against the application. The RED is recorded, the boundary is declared, and the twelve capabilities the chase produced stay experimental.',
395			},
396			supportBoundary: ANGULAR_PRE_IVY_SUPPORT_BOUNDARY,
397			nonclaims: [
398				...(Array.isArray(migration.notEstablished)
399					? migration.notEstablished.map((claim, index) =>
400							text(claim, `pigallery2 non-claim[${index}]`),
401						)
402					: []),
403				...HOLDOUT_ANGULAR_PIGALLERY2_ADDED_NONCLAIMS,
404			],
405			integrity: { algorithm: 'sha256', canonicalDigest: '' },
406		};
407		receipt.integrity.canonicalDigest = holdoutAngularPigallery2Digest(receipt);
408		return receipt;
409	}
