411	/**
412	 * Parses a published receipt and refuses one whose claims have moved.
413	 *
414	 * The outcome, the counting-relevant fields and the boundary declaration are
415	 * checked explicitly rather than only by digest, so an edit that recomputed the
416	 * digest consistently with itself is still caught.
417	 */
418	export function parseHoldoutAngularPigallery2Receipt(
419		value: unknown,
420	): HoldoutAngularPigallery2Receipt {
421		const receipt = record(value, 'pigallery2 holdout receipt') as unknown as
422			HoldoutAngularPigallery2Receipt;
423		if (
424			receipt.schemaVersion !== HOLDOUT_ANGULAR_PIGALLERY2_SCHEMA ||
425			receipt.role !== 'holdout' ||
426			receipt.holdoutOutcome !== 'failed' ||
427			receipt.reason !== HOLDOUT_ANGULAR_PIGALLERY2_MISSING_CAPABILITY ||
428			receipt.application !== HOLDOUT_ANGULAR_PIGALLERY2_APPLICATION ||
429			receipt.framework !== 'angular'
430		)
431			throw new Error('pigallery2 holdout receipt identity or outcome differs');
432		if (
433			receipt.lanes?.baseline?.outcome !== 'green' ||
434			receipt.lanes?.migrated?.outcome !== 'red' ||
435			receipt.lanes?.migrated?.artifactProduced !== false ||
436			receipt.frozenAdapter?.applicationFilesHandEdited !== 0 ||
437			receipt.frozenAdapter?.bytesChangedAtIngestion !== 0
438		)
439			throw new Error('pigallery2 holdout lanes or influence differ');
440		if (
441			receipt.finding?.libraries !== 3 ||
442			receipt.finding?.importSites !== 6 ||
443			receipt.supportBoundary?.state !== 'unsupported' ||
444			receipt.supportBoundary?.condition !== ANGULAR_PRE_IVY_SUPPORT_BOUNDARY.condition
445		)
446			throw new Error('pigallery2 holdout finding or support boundary differs');
447		if (
448			!Array.isArray(receipt.nonclaims) ||
449			!HOLDOUT_ANGULAR_PIGALLERY2_ADDED_NONCLAIMS.every((claim) =>
450				receipt.nonclaims.includes(claim),
451			)
452		)
453			throw new Error('pigallery2 holdout non-claims differ');
454		if (
455			receipt.integrity?.algorithm !== 'sha256' ||
456			!sha256Hex.test(receipt.integrity.canonicalDigest) ||
457			receipt.integrity.canonicalDigest !== holdoutAngularPigallery2Digest(receipt)
458		)
459			throw new Error('pigallery2 holdout integrity differs');
460		return receipt;
461	}
462	
463	export function renderHoldoutAngularPigallery2Receipt(
464		receipt: HoldoutAngularPigallery2Receipt,
465	): string {
466		const boundary = receipt.supportBoundary;
467		return `# pigallery2 1.7.0 — Angular holdout falsification receipt
468	
469	- Outcome: **${receipt.holdoutOutcome}** — the frozen Angular adapter does not carry this application at this revision
470	- Recorded reason: **${receipt.reason}**
471	- Canonical SHA-256: ${receipt.integrity.canonicalDigest}
