506	
507	## Non-claims
508	
509	${receipt.nonclaims.map((claim) => `- ${claim}`).join('\n')}
510	`;
511	}
512	
513	/**
514	 * The corpus and aggregate record for this holdout.
515	 *
516	 * It follows the cypress-realworld-app record field for field: a holdout that
517	 * failed is evidence about the adapter, not a migrated application, so it is
518	 * never an aggregate fixture row and never a Judge counting cell, and
519	 * `countedInLineageNumerator` is false and stays false.
