521	export function holdoutAngularPigallery2CorpusRecord(receipt: HoldoutAngularPigallery2Receipt) {
522		return {
523			id: 'holdout-angular-pigallery2',
524			application: receipt.application,
525			framework: receipt.framework,
526			lineage: 'angular',
527			role: 'holdout',
528			attempted: true,
