			wall: HOLDOUT_ANGULAR_PIGALLERY2_WALL.map((entry) => ({
				...entry,
				importSites: [...entry.importSites],
			})),
			libraries: 3,
			importSites: 6,
			downstreamReading: text(migration.downstreamReading, 'pigallery2 downstream reading'),
